probes.act0:
local a, b = H.node(H.pawn(0)), H.node(H.pawn(0), 1)
local function busy(n) n = tostring(n or ''); return n ~= '' and not n:find('Locomotion', 1, true) and not n:find('UpperBodyDefault', 1, true) and not n:find('Liv', 1, true) end
return busy(a) or busy(b)

